const STORAGE_KEY = 'antunes-os-mvp-v1';
const initialData = {
  clientes:[{id:1,nome:'Café Horizonte',contato:'Marina Lopes',status:'Ativo',email:'marina@exemplo.com'},{id:2,nome:'Studio Norte',contato:'Lucas Martins',status:'Prospecção',email:'lucas@exemplo.com'}],
  oportunidades:[{id:3,nome:'Novo site institucional',cliente:'Café Horizonte',valor:'4800',etapa:'Proposta'},{id:4,nome:'Automação de atendimento',cliente:'Studio Norte',valor:'3200',etapa:'Diagnóstico'}],
  projetos:[{id:5,nome:'Portal Café Horizonte',cliente:'Café Horizonte',status:'Em andamento',prazo:'2026-10-20'}],
  tarefas:[{id:6,nome:'Revisar briefing do portal',projeto:'Portal Café Horizonte',status:'Pendente',prazo:'2026-09-26'},{id:7,nome:'Preparar proposta comercial',projeto:'Studio Norte',status:'Pendente',prazo:'2026-09-27'}],
  notas:[{id:8,nome:'Princípio de operação',conteudo:'Entender o problema antes de sugerir tecnologia.',categoria:'DNA da empresa'}],
  parceiros:[{id:9,nome:'Ana Ribeiro',especialidade:'Design de interfaces',status:'Disponível',contato:'ana@exemplo.com'}]
};
let state = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null') || initialData;
let currentView = 'dashboard';
const labels={clientes:'Clientes',oportunidades:'Oportunidades',projetos:'Projetos',tarefas:'Tarefas',notas:'Notas',parceiros:'Parceiros'};
const schemas={
  clientes:[['nome','Nome da empresa'],['contato','Pessoa de contato'],['email','E-mail'],['status','Status','select',['Prospecção','Ativo','Inativo']]],
  oportunidades:[['nome','Oportunidade'],['cliente','Cliente'],['valor','Valor estimado (R$)','number'],['etapa','Etapa','select',['Diagnóstico','Proposta','Negociação','Ganho','Perdido']]],
  projetos:[['nome','Nome do projeto'],['cliente','Cliente'],['status','Status','select',['Planejamento','Em andamento','Pausado','Concluído']],['prazo','Prazo','date']],
  tarefas:[['nome','Tarefa'],['projeto','Projeto ou contexto'],['status','Status','select',['Pendente','Em andamento','Concluída']],['prazo','Prazo','date']],
  notas:[['nome','Título'],['categoria','Categoria'],['conteudo','Conteúdo','textarea']],
  parceiros:[['nome','Nome'],['especialidade','Especialidade'],['contato','Contato'],['status','Status','select',['Disponível','Em projeto','Indisponível']]]
};
const content=document.querySelector('#content'), dialog=document.querySelector('#record-dialog'), form=document.querySelector('#record-form');
const save=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const badge=value=>`<span class="badge ${/ativo|ganho|conclu/i.test(value)?'green':/proposta|andamento/i.test(value)?'yellow':/perdido|inativo/i.test(value)?'red':''}">${value||'—'}</span>`;
const escapeHTML=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),1900)}
function render(){document.querySelector('#page-title').textContent=currentView==='dashboard'?'Visão geral':labels[currentView];document.querySelector('#page-kicker').textContent=currentView==='dashboard'?'CENTRAL DE OPERAÇÃO':'GESTÃO · '+labels[currentView].toUpperCase();document.querySelector('#new-item').textContent=currentView==='dashboard'?'+ Novo registro':`+ Novo ${labels[currentView].slice(0,-1)}`; currentView==='dashboard'?renderDashboard():renderModule(currentView)}
function renderDashboard(){
 const pipeline=state.oportunidades.slice(0,3).map(x=>`<div class="stage"><small>${escapeHTML(x.etapa)}</small><strong>${escapeHTML(x.nome)}</strong><span>${escapeHTML(x.cliente)} · ${money(x.valor)}</span></div>`).join('')||'<div class="empty">Nenhuma oportunidade.</div>';
 const tasks=state.tarefas.filter(x=>x.status!=='Concluída').slice(0,4).map(x=>`<li><button class="task-check" data-complete="${x.id}" aria-label="Concluir tarefa"></button><div class="task-copy"><b>${escapeHTML(x.nome)}</b><small>${escapeHTML(x.projeto)} · ${x.prazo?new Date(x.prazo+'T12:00').toLocaleDateString('pt-BR'):'sem prazo'}</small></div>${badge(x.status)}</li>`).join('')||'<li><div class="task-copy"><b>Tudo em dia</b><small>Nenhuma tarefa pendente.</small></div></li>';
 const today=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'});
 content.innerHTML=`<div class="welcome"><div><h2>Bom trabalho, <span>Gabriel.</span></h2><p>Este é o centro de operação da Antunes Digital. Comece pequeno, registre tudo e deixe o processo revelar o próximo passo.</p></div><span class="date-chip">${today}</span></div><div class="metric-grid"><article class="metric"><div><span>CLIENTES ATIVOS</span><i></i></div><strong>${state.clientes.filter(x=>x.status==='Ativo').length}</strong></article><article class="metric"><div><span>OPORTUNIDADES</span><i></i></div><strong>${state.oportunidades.length}</strong></article><article class="metric"><div><span>PROJETOS ABERTOS</span><i></i></div><strong>${state.projetos.filter(x=>x.status!=='Concluído').length}</strong></article><article class="metric"><div><span>TAREFAS PENDENTES</span><i></i></div><strong>${state.tarefas.filter(x=>x.status!=='Concluída').length}</strong></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h3>Pipeline comercial</h3><button data-go="oportunidades">Ver todas →</button></div><div class="pipeline">${pipeline}</div></section><section class="panel"><div class="panel-head"><h3>Próximas tarefas</h3><button data-go="tarefas">Ver todas →</button></div><ul class="task-list">${tasks}</ul></section></div>`;
}
function renderModule(type,query=''){
 const items=state[type].filter(x=>Object.values(x).join(' ').toLowerCase().includes(query.toLowerCase()));
 const intro={clientes:'Organize contatos e o histórico de relacionamento.',oportunidades:'Acompanhe cada conversa do diagnóstico ao fechamento.',projetos:'Controle entregas, responsáveis e próximos marcos.',tarefas:'Centralize o que precisa acontecer e quando.',notas:'Registre decisões, aprendizados e o DNA da empresa.',parceiros:'Mantenha sua rede de especialistas pronta para cada projeto.'}[type];
 let body='';
 if(['notas','parceiros','projetos'].includes(type)) body=`<div class="card-list">${items.map(item=>card(type,item)).join('')}</div>`;
 else body=table(type,items);
 if(!items.length) body='<div class="empty"><strong>Nenhum registro encontrado.</strong>Crie o primeiro registro deste módulo.</div>';
 content.innerHTML=`<div class="view-head"><div><h2>${labels[type]}</h2><p>${intro}</p></div><input class="search" id="search" placeholder="Buscar em ${labels[type].toLowerCase()}..." value="${escapeHTML(query)}"></div>${body}`;
 document.querySelector('#search')?.addEventListener('input',e=>renderModule(type,e.target.value));
}
function table(type,items){const config={clientes:['Empresa','Contato','E-mail','Status'],oportunidades:['Oportunidade','Cliente','Valor','Etapa'],tarefas:['Tarefa','Contexto','Prazo','Status']}[type];return `<div class="table-wrap"><table class="data-table"><thead><tr>${config.map(x=>`<th>${x}</th>`).join('')}<th></th></tr></thead><tbody>${items.map(x=>{let cells= type==='clientes'?[`<span class="row-title">${escapeHTML(x.nome)}</span>`,escapeHTML(x.contato),escapeHTML(x.email),badge(x.status)]:type==='oportunidades'?[`<span class="row-title">${escapeHTML(x.nome)}</span>`,escapeHTML(x.cliente),money(x.valor),badge(x.etapa)]:[`<span class="row-title">${escapeHTML(x.nome)}</span>`,escapeHTML(x.projeto),x.prazo?new Date(x.prazo+'T12:00').toLocaleDateString('pt-BR'):'—',badge(x.status)];return `<tr>${cells.map(c=>`<td>${c}</td>`).join('')}<td><button class="delete" data-delete="${type}:${x.id}" aria-label="Excluir">×</button></td></tr>`}).join('')}</tbody></table></div>`}
function card(type,x){const meta=type==='projetos'?`${x.cliente} · ${x.prazo?new Date(x.prazo+'T12:00').toLocaleDateString('pt-BR'):'sem prazo'}`:type==='notas'?x.categoria:x.especialidade;const text=type==='notas'?x.conteudo:type==='projetos'?'Acompanhe o andamento e mantenha o próximo passo visível.':x.contato;const status=type==='notas'?'NOTA':x.status;return `<article class="record-card"><small>${escapeHTML(status)}</small><h3>${escapeHTML(x.nome)}</h3><p>${escapeHTML(text)}</p><footer><span class="row-sub">${escapeHTML(meta)}</span><button class="delete" data-delete="${type}:${x.id}" aria-label="Excluir">×</button></footer></article>`}
function openDialog(type){if(type==='dashboard')type='clientes';document.querySelector('#dialog-title').textContent=`Adicionar em ${labels[type]}`;document.querySelector('#dialog-kicker').textContent='NOVO REGISTRO · '+labels[type].toUpperCase();form.dataset.type=type;document.querySelector('#form-fields').innerHTML=schemas[type].map(([key,label,kind='text',options])=>{const wide=kind==='textarea'?'wide':'';if(kind==='select')return `<label class="${wide}">${label}<select name="${key}" required>${options.map(o=>`<option>${o}</option>`).join('')}</select></label>`;if(kind==='textarea')return `<label class="wide">${label}<textarea name="${key}" rows="4" required></textarea></label>`;return `<label class="${wide}">${label}<input name="${key}" type="${kind}" required></label>`}).join('');dialog.showModal()}
document.querySelector('#nav').addEventListener('click',e=>{const btn=e.target.closest('[data-view]');if(!btn)return;currentView=btn.dataset.view;document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x===btn));document.querySelector('.sidebar').classList.remove('open');render()});
content.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){currentView=go.dataset.go;document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===currentView));render()}const del=e.target.closest('[data-delete]');if(del&&confirm('Excluir este registro?')){const [type,id]=del.dataset.delete.split(':');state[type]=state[type].filter(x=>x.id!==Number(id));save();render();toast('Registro excluído')}const done=e.target.closest('[data-complete]');if(done){const task=state.tarefas.find(x=>x.id===Number(done.dataset.complete));if(task){task.status='Concluída';save();render();toast('Tarefa concluída')}}});
document.querySelector('#new-item').addEventListener('click',()=>openDialog(currentView));document.querySelector('#close-dialog').onclick=()=>dialog.close();document.querySelector('#cancel-dialog').onclick=()=>dialog.close();document.querySelector('#mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
form.addEventListener('submit',e=>{e.preventDefault();const type=form.dataset.type;const item={id:Date.now(),...Object.fromEntries(new FormData(form))};state[type].unshift(item);save();dialog.close();form.reset();if(currentView==='dashboard')currentView=type;document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===currentView));render();toast('Registro salvo')});
render();
